    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "project_id" uuid NOT NULL,
    "floatingip_id" uuid NOT NULL,
    "internal_port_id" uuid NOT NULL,
    "internal_ip_address" varchar(50) NOT NULL,
    "external_port" integer NOT NULL,
    "internal_port" integer NOT NULL,
    "protocol" varchar(10) NOT NULL,
    "status" varchar(50) DEFAULT 'ACTIVE'::character varying,
    "description" text,
    "created_at" timestamp DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "port_forwardings_pkey" PRIMARY KEY (id),
    CONSTRAINT "port_forwardings_floatingip_id_external_port_protocol_key" UNIQUE (floatingip_id, external_port, protocol),
    CONSTRAINT "port_forwardings_external_port_check" CHECK (((external_port >= 1) AND (external_port <= 65535))),
    CONSTRAINT "port_forwardings_internal_port_check" CHECK (((internal_port >= 1) AND (internal_port <= 65535))),
    CONSTRAINT "port_forwardings_protocol_check" CHECK (protocol IN ('tcp', 'udp'))
);
CREATE TABLE "snapshot_metadata" (
    "id" uuid NOT NULL DEFAULT gen_random_uuid(),
