-- The applied-state record (SPEC-032 FR-019); its presence marks a post-squash database.
CREATE TABLE applied_migrations (
    version    BIGINT      PRIMARY KEY,
    checksum   TEXT        NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO applied_migrations (version, checksum) VALUES (1, 'f948ebf67eb8ce1e1b0918a760b674d8bc5b37e9e03b81506e4e1ef1b6488531');
